mapper.select:
SELECT ub.id,ub.link_id AS linkId,ub.pm,ub.title,ub.category,ub.type,ub.number,ub.balance,ub.mark,ub.status,ub.create_time AS createTime,ub.update_time AS updateTime,u.nickname,ub.uid FROM eb_user_bill ub
LEFT JOIN eb_user u ON ub.uid = u.uid
where 1 = 1

    and ( ub.id like #{keywords} or ub.uid like #{keywords} or ub.link_id like #{keywords, jdbcType=VARCHAR} or ub.title like #{keywords, jdbcType=VARCHAR} or u.nickname like #{keywords, jdbcType=VARCHAR})


    and ub.type = #{type, jdbcType=VARCHAR}


    and ub.category = #{category, jdbcType=VARCHAR}


    and ub.uid in 

        #{userIdList}



    and (ub.create_time between #{startTime} and #{endTime})


ORDER BY ub.id DESC,ub.create_time DESC

SELECT ub.id,ub.link_id AS linkId,ub.pm,ub.title,ub.category,ub.type,ub.number,ub.balance,ub.mark,ub.status, ub.create_time AS createTime,ub.update_time AS updateTime,u.nickname,ub.uid,u.phone,u.avatar FROM eb_user_bill ub LEFT JOIN eb_user u ON ub.uid = u.uid where ub.category IN ('now_money','brokerage_price')
and ub.category = #{category, jdbcType=VARCHAR}
and ub.title = #{title, jdbcType=VARCHAR}
and ub.title in #{tItem}
and (
ub.title like CONCAT('%',#{tItem},'%')
)
and (ub.create_time between #{startTime} and #{endTime})
and ( ub.uid like CONCAT('%',#{keywords},'%') or u.nickname like CONCAT('%',#{keywords},'%') or u.phone like CONCAT('%',#{keywords},'%') )
and ub.uid = #{uid}
and u.nickname like CONCAT('%',#{nickname},'%')
and u.phone like CONCAT('%',#{phone},'%')
and ( ub.link_id like CONCAT('%',#{linkId},'%') or exists ( select 1 from eb_store_order so where so.order_id like CONCAT('%',#{linkId},'%') and (ub.link_id = so.order_id or ub.link_id = CONVERT(so.id, CHAR) COLLATE utf8mb4_general_ci) ) )
ORDER BY ub.id DESC,ub.create_time DESC
